#!/usr/bin/env node
// ACH-014 apis-integracoes: example JSON Schema generator.
//
// Non-TypeScript consumers (iOS native in the future, parceiros de
// marketplace que não usam Node, scripts de integração) can't consume
// the `AppRouter` type generated by tRPC. This script is a proof of
// concept for exposing Zod schemas as JSON Schema — the sibling doc
// (`docs/architecture/api-spec.md`) compares this approach against
// `trpc-openapi` (a heavier solution that also publishes route
// metadata).
//
// Usage:
//   node scripts/generate-api-schema.mjs <SchemaName> [--out json]
//
// Example:
//   node scripts/generate-api-schema.mjs createClientSchema
//
// Produces JSON Schema derived from the Zod schema via
// `zod-to-json-schema`. Install that package locally before running.

import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { dirname } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(__dirname, "..");

const schemaName = process.argv[2];
const format =
  process.argv.indexOf("--out") > 0
    ? process.argv[process.argv.indexOf("--out") + 1]
    : "pretty";

if (!schemaName) {
  console.error(
    "usage: node scripts/generate-api-schema.mjs <SchemaName> [--out json|pretty]",
  );
  process.exit(2);
}

async function main() {
  let zodToJsonSchema;
  try {
    ({ zodToJsonSchema } = await import("zod-to-json-schema"));
  } catch {
    console.error(
      "Missing dep: install `zod-to-json-schema` before running this generator.",
    );
    console.error("  pnpm add -D zod-to-json-schema --filter @wbc/...");
    process.exit(2);
  }

  const validators = await import(
    resolve(repoRoot, "packages/validators/src/index.ts")
  );
  const schema = validators[schemaName];
  if (!schema) {
    console.error(`Unknown schema: ${schemaName}`);
    console.error(
      `Available: ${Object.keys(validators)
        .filter((k) => k.endsWith("Schema"))
        .sort()
        .join(", ")}`,
    );
    process.exit(2);
  }

  const jsonSchema = zodToJsonSchema(schema, { name: schemaName });
  const out =
    format === "json"
      ? JSON.stringify(jsonSchema)
      : JSON.stringify(jsonSchema, null, 2);
  process.stdout.write(out + "\n");
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
